&lt;div class="c-embed__content"&gt;
&lt;div class="c-embed__body flex items-center justify-between"&gt;
&lt;a href="https://sparkforge3.gumroad.com/l/udishn" rel="noopener noreferrer" class="c-link fw-bold flex items-center"&gt;
